import {top,shell,nav,petCard,ledgerAsset as A,chevron} from './screens.js';
import {categories,todayDate,cents,money,splitCents,billAmount,summary,investment,saveBill,removeBill,undoBill,refundAllocations,remainingAllocations} from './ledger-model.js';
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const S=id=>A(id,'ui-surface');
const petSticker=p=>p?.kind==='狗狗'?'<img class="ui-asset ld-worth-cat ld-worth-dog" src="./assets/dog/1700-1947.svg" alt="狗狗贴纸">':p&&p.kind!=='猫咪'?'<svg class="ld-worth-cat ld-worth-other" viewBox="0 0 92 66" role="img" aria-label="宠物爪印贴纸"><path d="M30 40C35 29 46 23 55 33L69 48C71 59 61 63 52 57C48 55 44 55 40 58C27 65 17 59 22 49Z" fill="none" stroke="#454139" stroke-width="3"/><ellipse cx="24" cy="27" rx="7" ry="10" fill="none" stroke="#454139" stroke-width="3"/><ellipse cx="41" cy="16" rx="7" ry="10" fill="none" stroke="#454139" stroke-width="3"/><ellipse cx="60" cy="19" rx="7" ry="10" fill="none" stroke="#454139" stroke-width="3"/></svg>':A('741','ld-worth-cat');
const yen=n=>'¥'+money(n);
const day=t=>new Date(t+'T12:00').toLocaleDateString('zh-CN',{month:'long',day:'numeric'});
const home=()=>`<div class="ld-home">${A('620')}</div>`;
const primary=(text,attrs='',id='494')=>`<button class="ld-primary" ${attrs}>${S(id)}<span>${text}</span></button>`;
const splitOwners=(state,bill)=>{const pets=[...state.pets];for(const a of bill?.allocations||[])if(a.petId&&!pets.some(p=>p.id===a.petId))pets.push({id:a.petId,name:a.petName});return pets;};
const owner=(a,state)=>a.petId===null?'公共支出':a.petName+(state.pets.some(p=>p.id===a.petId)?'':'（已删除）');
function options(state,current,all=true){const choices=new Map(state.pets.map(p=>[p.id,p.name]));for(const b of state.bills)for(const a of b.allocations)if(a.petId&&!choices.has(a.petId))choices.set(a.petId,a.petName+'（已删除）');return `${all?`<option value="all" ${current==='all'?'selected':''}>全部宠物与公共支出</option>`:''}${[...choices].map(([id,n])=>`<option value="${E(id)}" ${current===id?'selected':''}>${E(n)}</option>`).join('')}<option value="public" ${current==='public'?'selected':''}>公共支出</option>`;}
function scopePicker(c,control='ledgerScope',selected=c.ledger.scope){const p=c.state.pets.find(p=>p.id===selected);return `<label class="ld-picker" title="选择账单归属">${S('650')}<span class="ld-picker-avatar">${A('655')}${selected==='all'||selected==='public'||!p?'<img class="ld-scope-paw" src="./assets/pet-switch/1694-1876.svg" alt="全部宠物与公共支出">':p.avatar?`<img class="ld-user-avatar" src="${E(p.avatar)}" alt="${E(p.name)}">`:p.kind==='狗狗'?'<img class="ld-picker-dog" src="./assets/dog/1700-1951.svg" alt="狗狗">':A('656')}</span>${A('652','ld-picker-down')}<select id="${control}" aria-label="记账宠物筛选">${options(c.state,selected,control!=='billHeaderPet')}</select></label>`;}
function header(c,title,back,picker=true){return top(c,title,back)+(picker?scopePicker(c,c.page==='billform'?'billHeaderPet':'ledgerScope'):'');}
const scopeLabel=c=>c.ledger.scope==='all'?'全部宠物':c.ledger.scope==='public'?'公共支出':c.state.pets.find(p=>p.id===c.ledger.scope)?.name||c.state.bills.flatMap(b=>b.allocations).find(a=>a.petId===c.ledger.scope)?.petName||'宠物';
function icon(category){return `${A('474','ld-icon-bg')}${category==='食品'?A('764','ld-food-icon'):category==='清洁'?A('765','ld-clean-icon'):category==='医疗'?'<img class="ld-medical-icon" src="./assets/screens/1667-3066.svg" alt="医疗">':''}`;}
function rows(c,bills,compact=false){return bills.map(b=>`<button class="${compact?'ld-large-row':'ld-bill-row'}" data-bill="${E(b.id)}">${compact?'':S('473')+`<span class="ld-bill-icon">${icon(b.category)}</span>`}<span class="ld-bill-copy"><strong>${b.type==='refund'?'退款 · ':''}${E(b.name)}</strong><small>${E(b.category)}${compact||c.ledger.scope==='all'?' · '+day(b.date):''}${c.ledger.scope==='all'?' · '+E(b.allocations.length>1?'多宠分摊':owner(b.allocations[0],c.state)):''}</small></span><b>${b.type==='refund'?'−':''}${yen(billAmount(b,c.ledger.scope))}</b>${chevron()}</button>`).join('');}
function ledger(c){const u=c.ledger,total=investment(c.state,u.scope),month=summary(c.state,u.scope,u.month),recent=summary(c.state,u.scope).rows.slice(0,8),p=c.state.pets.find(p=>p.id===u.scope);let companion='记下每一份陪伴与投入';if(p?.arrival){const days=Math.floor((new Date(todayDate()+'T12:00')-new Date(p.arrival+'T12:00'))/86400000);if(days>=0)companion=`陪伴${days+1}天啦~`;}const deleted=c.state.bills.filter(b=>b.deletedAt).sort((a,b)=>b.deletedAt.localeCompare(a.deletedAt))[0];return shell(header(c,'养宠账本')+`<div class="ld-main"><button class="ld-worth" data-ledger-invest>${S('457')}<strong>${u.scope==='all'?'全部花费':E(scopeLabel(c))+(u.scope==='public'?'累计投入':'的身价')}</strong><b>${yen(total.total)}</b><small>累计养宠投入</small><small>${companion}</small>${petSticker(p)}</button><section class="ld-month-summary">${S('463')}<label class="ld-month-label"><strong>${Number(u.month.slice(5))}月</strong><input id="ledgerMonth" type="month" value="${u.month}" aria-label="账本月份"></label><button data-ledger-analysis>查看统计 ${chevron()}</button><small>本月支出</small><div><b>${yen(month.net)}</b><strong>共${month.count}笔</strong></div><p>分类支出 ${Object.entries(month.byCategory).map(([k,v])=>`${k} ${yen(v)}`).join(' · ')||'暂无支出'}${month.refund?'；退款 '+yen(month.refund):''}</p></section>${primary('记一笔','data-ledger-new')}<div class="ld-recent-heading"><h2>最近账单</h2><button data-go="billlist">查看全部 ${chevron()}</button></div><small class="ld-recent-date">${recent.length?day(recent[0].date):'从第一笔养宠支出开始'}</small><div class="ld-recent">${recent.length?rows(c,recent):'<div class="ld-empty">还没有账单，记下第一笔吧。</div>'}</div>${deleted?`<button class="ld-undo" data-undo-bill="${E(deleted.id)}">撤销最近删除的账单</button>`:''}</div>`+nav('ledger'),'ledger');}
function photoSection(photos,detail=false){return `<h2 class="ld-photo-title">照片（可选）</h2><div class="ld-photos"><div id="billPhotos">${photos.map((p,i)=>`<div><img src="${E(p)}" alt="账单照片"><button type="button" data-remove-bill-photo="${i}" aria-label="移除照片${i+1}">×</button></div>`).join('')}</div><label class="ld-upload">${S('789')}${A('791')}<input id="billPhotoInput" type="file" accept="image/*" multiple hidden aria-label="添加账单照片"></label><label class="ld-upload">${S('790')}<span>＋</span><input id="billPhotoExtra" type="file" accept="image/*" multiple hidden aria-label="再添加账单照片"></label></div>`;}
function note(value,detail=false){return `<label class="ld-note">${S(detail?'572':'788')}<strong>备注</strong>${detail?`<p>${E(value||'暂无备注')}</p>`:`<textarea name="note" aria-label="账单备注" maxlength="500" placeholder="记录这笔支出的小细节…">${E(value||'')}</textarea>`}</label>`;}
function billform(c){const u=c.ledger,r=c.state.bills.find(b=>b.id===u.editId),parent=c.state.bills.find(b=>b.id===u.refundParent),refund=r?.type==='refund'||!!parent;const source=parent||r,selected=source?.allocations.length?source.allocations[0].petId:(u.scope==='all'?'':u.scope==='public'?null:u.scope);const amount=r?.cents??'';const allocated=(r?.allocations.length||0)>1;return shell(header(c,refund?'记退款':r?'编辑账单':'记一笔',u.formOrigin||'ledger',!r)+`<form id="billForm" class="ld-form"><label class="ld-amount">${S('516')}<small>金额（元）</small><div><b>¥</b><input name="amount" required type="text" inputmode="decimal" maxlength="12" aria-label="账单金额" placeholder="0.00" value="${amount!==''?(amount/100).toFixed(2):''}"></div></label><h2 class="ld-category-title">支出分类</h2><div class="ld-categories" role="radiogroup" aria-label="支出分类">${categories.map((name,i)=>`<label>${S('522')}${A('520','ld-category-active')}<input type="radio" name="category" value="${name}" ${name===(source?.category||'食品')?'checked':''} ${refund?'disabled':''}><span>${name}</span></label>`).join('')}</div><div class="ld-bill-fields">${S('532')}<label><strong>所属宠物</strong><select name="petId" aria-label="账单所属宠物" ${refund?'disabled':''}>${selected===''?'<option value="">请选择</option>':''}${options(c.state,selected===null?'public':selected,false)}</select>${chevron()}</label><label><strong>日期</strong><span id="billDateDisplay">${day(r?.date||todayDate())}</span><input name="date" type="date" required aria-label="账单日期" max="${todayDate()}" value="${r?.date||todayDate()}">${chevron()}</label><label><strong>名称</strong><input name="name" required maxlength="60" aria-label="账单名称" placeholder="支出名称" value="${E(r?.name||parent?.name||'')}">${chevron()}</label></div><label class="ld-toggle-row">${S('912')}<span>多只宠物分摊</span><input id="billSplit" type="checkbox" role="switch" aria-label="多只宠物分摊" ${allocated?'checked':''} ${refund?'disabled':''}><span class="ui-toggle"></span></label><div id="billSplitPanel" class="ld-split-panel" ${allocated&&!refund?'':'hidden'}>${splitOwners(c.state,r).map(p=>{const old=r?.allocations.find(a=>a.petId===p.id);return `<label><input type="checkbox" name="splitPet" value="${E(p.id)}" aria-label="分摊给${E(p.name)}" ${old?'checked':''}><span>${E(p.name)}</span><input data-allocation="${E(p.id)}" inputmode="decimal" aria-label="${E(p.name)}分摊金额" value="${old?(old.cents/100).toFixed(2):''}" placeholder="0.00"><small>元</small></label>`;}).join('')}<button type="button" id="equalSplit">平均分摊</button><small>各宠物分摊金额合计应等于总金额</small></div>${note(r?.note)}${photoSection(u.photos)}${primary(refund?'保存退款':'保存账单','type="submit"','548')}</form>`+home(),'billform','ld-secondary');}
function detail(c){const u=c.ledger,b=c.state.bills.find(b=>b.id===u.editId&&!b.deletedAt);if(!b)return shell(header(c,'账单详情',u.detailOrigin||'ledger',false)+'<div class="ld-empty">账单已删除</div>'+home(),'billdetail','ld-secondary');const allocated=b.allocations.find(a=>u.scope==='public'?a.petId===null:a.petId===u.scope),share=allocated?.cents??b.cents;return shell(header(c,'账单详情',u.detailOrigin||'ledger',false)+`<div class="ld-detail-main"><section class="ld-detail-summary">${S('558')}<b>${b.type==='refund'?'−':''}${yen(b.cents)}</b><div><strong>${E(b.name)}</strong><span>${S('561')}<small>${E(b.category)}</small></span></div></section><div class="ld-detail-fields">${S('563')}<div><span>所属宠物</span><span>${E(b.allocations.length>1?'多宠分摊':owner(b.allocations[0],c.state))}</span>${chevron()}</div><div><span>日期</span><span>${day(b.date)}</span>${chevron()}</div><button id="viewAllocations"><span>分摊金额</span><span>${yen(share)}</span>${chevron()}</button></div><div id="allocationDetails" class="ld-allocation-details" hidden>${b.allocations.map(a=>`<p><span>${E(owner(a,c.state))}</span><b>${yen(a.cents)}</b></p>`).join('')}</div>${note(b.note,true)}${photoSection(b.photos,true)}<label class="ld-toggle-row">${S('804')}<span>关联用品库存</span><input id="billInventory" type="checkbox" role="switch" aria-label="账单关联用品库存"><span class="ui-toggle"></span></label>${primary('编辑账单','id="editBill"','582')}<button class="ld-delete" id="deleteBill">${S('584')}<span>删除账单</span></button>${b.type==='expense'?`<button class="ld-refund" id="refundBill">记录退款${c.state.bills.some(x=>!x.deletedAt&&x.parentId===b.id)?' · 查看退款余额':''}</button>`:''}</div>`+home(),'billdetail','ld-secondary');}
function settings(c){const u=c.ledger,p=c.state.pets.find(p=>p.id===u.settingScope),totals=investment(c.state,u.settingScope);return shell(header(c,'累计投入设置','ledger',false)+(p?petCard(p):`<div class="ld-setting-owner"><strong>公共支出</strong><small>共同养宠投入</small></div>`)+`<form id="investmentForm"><div class="ld-initial-card">${S('600')}<label><span>初始投入（元）</span><span>编辑 ${chevron()}</span></label><div><b>¥</b><input name="initial" inputmode="decimal" aria-label="初始投入" required value="${(totals.initial/100).toFixed(2)}"></div><small>可包含领养、购买和此前养宠支出，允许为0。</small></div><section class="ld-invest-calculation">${S('604')}<h2>累计投入计算</h2><p><span>初始投入</span><i></i><span id="initialPreview">${yen(totals.initial)}</span></p><p><span>已记支出</span><i></i><span>${yen(totals.expense)}</span></p><p><span>已退款</span><i></i><span>−${yen(totals.refund)}</span></p><div><strong>累计投入</strong><b id="investmentPreview">${yen(totals.total)}</b></div></section><div class="ld-invest-warning">${S('615')}${A('910')}<p>已录入账本的支出，<br>请勿重复计入初始投入。</p></div>${primary('保存设置','type="submit"','618')}</form>`+home(),'investment','ld-secondary');}
const colors=['#cdb694','#a8dcee','#ddd7c7','#bfbca8','#d7bba6','#a7b7a2'];
function donut(totals){const values=Object.entries(totals.byCategory),sum=totals.expense;let offset=0;return `<svg class="ld-donut" viewBox="0 0 104 104" role="img" aria-label="分类支出占比"><circle cx="52" cy="52" r="42" fill="none" stroke="#ddd7c7" stroke-width="16"/>${values.map(([name,n],i)=>{const length=sum?n/sum*100:0,old=offset;offset+=length;return `<circle cx="52" cy="52" r="42" pathLength="100" fill="none" stroke="${colors[i]}" stroke-width="16" stroke-dasharray="${length} ${100-length}" stroke-dashoffset="${-old}" transform="rotate(-90 52 52)"/>`;}).join('')}<text x="52" y="59" text-anchor="middle" fill="#454139" font-size="16" font-weight="700">${sum?yen(sum).replace('.00',''):'¥0'}</text></svg>`;}
function bars(c,totals){const u=c.ledger,annual=u.period==='year',groups=new Map();let labels;if(annual){labels=Array.from({length:12},(_,i)=>String(i+1));}else if(u.trend==='week'){labels=['1周','2周','3周','4周','5周'];}else{const end=u.month===todayDate().slice(0,7)?Number(todayDate().slice(8)):new Date(Number(u.month.slice(0,4)),Number(u.month.slice(5)),0).getDate();labels=Array.from({length:Math.min(7,end)},(_,i)=>String(Math.max(1,end-6)+i));}for(const b of totals.rows){if(b.type==='refund')continue;const key=annual?String(Number(b.date.slice(5,7))):u.trend==='week'?Math.ceil(Number(b.date.slice(8))/7)+'周':String(Number(b.date.slice(8)));groups.set(key,(groups.get(key)||0)+billAmount(b,u.scope));}const max=Math.max(100,...labels.map(k=>groups.get(k)||0)),step=292/labels.length;return `<svg class="ld-bars" viewBox="0 0 362 134" role="img" aria-label="${annual?'全年各月':u.trend==='week'?'当月各周':'最近7日'}支出趋势"><line x1="43" x2="337" y1="108" y2="108" stroke="#716c5e"/>${[0,1,2,3].map(i=>`<text x="35" y="${111-i*31}" text-anchor="end" font-size="11" fill="#54555a">${Math.round(max*i/3/100)}</text>`).join('')}${labels.map((k,i)=>{const height=(groups.get(k)||0)/max*95;return `<rect x="${48+i*step+step*.13}" y="${108-height}" width="${step*.68}" height="${height}" rx="${Math.min(15,step*.34)}" fill="#cdb694"/><text x="${48+i*step+step*.47}" y="126" text-anchor="middle" font-size="11" fill="#54555a">${k}</text>`;}).join('')}</svg>`;}
function analysis(c){const u=c.ledger,annual=u.period==='year',period=annual?u.month.slice(0,4):u.month,t=summary(c.state,u.scope,period),last=new Date(Number(u.month.slice(0,4)),Number(u.month.slice(5)),0).getDate();return shell(header(c,'账单分析','ledger')+`<div class="ld-analysis-main"><div class="ld-analysis-period"><label><strong>${annual?period+'年':Number(u.month.slice(5))+'月'}</strong><span class="ui-down"></span><input id="analysisDate" type="${annual?'number':'month'}" aria-label="分析日期" value="${period}" ${annual?'min="2000" max="2100"':''}></label><div>${S('1112')}${['month','year'].map((v,i)=>`<button data-ledger-period="${v}" class="${u.period===v?'active':''}">${u.period===v?A('1113','ui-surface'):''}<span>${i?'年度':'月度'}</span></button>`).join('')}</div><small>日期范围：${annual?period+'年1月1日—12月31日':Number(u.month.slice(5))+'月1日—'+Number(u.month.slice(5))+'月'+last+'日'}</small></div><section class="ld-analysis-summary">${S('1054')}<div><small>${annual?'本年':'本月'}支出</small><b>${yen(t.net)}</b></div><div><small>支出笔数</small><b>${t.count}笔</b></div><small>实际净支出（支出减退款）</small></section><section class="ld-classification">${S('1060')}<h2>分类支出</h2>${donut(t)}<div class="ld-category-legend">${Object.entries(t.byCategory).map(([name,n],i)=>`<button data-bill-category="${name}"><i style="background:${colors[i]}"></i><span>${name}</span><b>${yen(n).replace('.00','')}</b><small>${Math.round(n/t.expense*100)}%</small></button>`).join('')||'<small>暂无分类支出</small>'}</div></section><section class="ld-trend">${S('1078')}<h2>支出趋势</h2><div class="ld-trend-tabs">${S('1080')}${['day','week'].map((x,i)=>`<button data-ledger-trend="${x}" class="${u.trend===x?'active':''}" ${annual?'disabled':''}>${u.trend===x?S('1081'):''}<span>${annual?i?'':'月':i?'周':'日'}</span></button>`).join('')}</div>${bars(c,t)}</section><section class="ld-large">${S('1096')}<h2>大额账单</h2><button class="ld-view-all" data-go="billlist">查看全部账单 ${chevron()}</button>${rows(c,t.rows.filter(b=>b.type==='expense').sort((a,b)=>billAmount(b,u.scope)-billAmount(a,u.scope)).slice(0,2),true)||'<p class="ld-empty">暂无账单</p>'}</section></div>`+home(),'analysis','ld-secondary');}
function list(c){const u=c.ledger,t=summary(c.state,u.scope,u.period==='year'?u.month.slice(0,4):u.month,u.category);return shell(header(c,'全部账单','ledger')+`<div class="ld-list-main"><label class="ld-list-month">月份<input id="ledgerMonth" type="month" aria-label="账本月份" value="${u.month}"></label><div class="ld-list-categories">${['全部',...categories].map(x=>`<button data-list-category="${x}" class="${u.category===x?'active':''}">${x}</button>`).join('')}</div><p class="ld-list-summary">${t.rows.length}笔 · 净支出 ${yen(t.net)}</p>${rows(c,t.rows)||'<div class="ld-empty">当前筛选没有账单</div>'}${primary('记一笔','data-ledger-new')}</div>`+home(),'billlist','ld-secondary');}
export function renderLedgerPage(page,c){return ({ledger,billform,billdetail:detail,investment:settings,analysis,billlist:list}[page])?.(c)??null;}
export function bindLedger(c,api){const $=s=>document.querySelector(s),u=c.ledger,form=$('#billForm');
const refresh=()=>api.render();const start=(bill=null,parent=null)=>{u.photos=[...(bill?.photos||[])];u.editId=bill?.id||null;u.refundParent=parent?.id||null;u.formOrigin=c.page==='billdetail'&&parent?'ledger':c.page;api.go('billform');};
$('#billHeaderPet')?.addEventListener('change',e=>{if(form){form.elements.petId.value=e.target.value;api.setDirty();}});
$('#ledgerScope')?.addEventListener('change',e=>{if(api.persist({...c.state,ledgerScope:e.target.value})){u.scope=e.target.value;refresh();}});
$('#ledgerMonth')?.addEventListener('change',e=>{if(e.target.value){u.month=e.target.value;u.period='month';refresh();}});
document.querySelectorAll('[data-ledger-new]').forEach(b=>b.onclick=()=>start());
document.querySelectorAll('[data-bill]').forEach(b=>b.onclick=()=>{u.editId=b.dataset.bill;u.detailOrigin=c.page;api.go('billdetail');});
document.querySelectorAll('[data-ledger-invest]').forEach(b=>b.onclick=()=>{u.settingScope=u.scope==='all'?(c.state.pets[0]?.id||'public'):u.scope;api.go('investment');});
document.querySelectorAll('[data-ledger-analysis]').forEach(b=>b.onclick=()=>{u.period='month';api.go('analysis');});
$('#analysisDate')?.addEventListener('change',e=>{const v=e.target.value;if(u.period==='year'){if(!/^\d{4}$/.test(v)||Number(v)<2000||Number(v)>2100)return api.toast('年份需为2000—2100');u.month=v+u.month.slice(4);}else if(v)u.month=v;refresh();});
document.querySelectorAll('[data-ledger-period]').forEach(b=>b.onclick=()=>{u.period=b.dataset.ledgerPeriod;refresh();});document.querySelectorAll('[data-ledger-trend]').forEach(b=>b.onclick=()=>{u.trend=b.dataset.ledgerTrend;refresh();});
document.querySelectorAll('[data-bill-category]').forEach(b=>b.onclick=()=>{u.category=b.dataset.billCategory;api.go('billlist');});document.querySelectorAll('[data-list-category]').forEach(b=>b.onclick=()=>{u.category=b.dataset.listCategory;refresh();});
$('#editBill')?.addEventListener('click',()=>start(c.state.bills.find(b=>b.id===u.editId)));
$('#viewAllocations')?.addEventListener('click',()=>$('#allocationDetails').hidden=!$('#allocationDetails').hidden);
$('#refundBill')?.addEventListener('click',()=>{const parent=c.state.bills.find(b=>b.id===u.editId);if(remainingAllocations(c.state,parent.id).reduce((s,a)=>s+a.cents,0)===0)return api.toast('这笔支出已经全部退款');start(null,parent);});
$('#deleteBill')?.addEventListener('click',()=>{if(!confirm('删除这笔账单？列表和统计会同步更新，可在账本撤销。'))return;try{if(api.persist(removeBill(c.state,u.editId))){api.clearDirty();api.go('ledger');api.toast('账单已删除，可撤销');}}catch(e){api.toast(e.message);}});
document.querySelectorAll('[data-undo-bill]').forEach(b=>b.onclick=()=>{try{if(api.persist(undoBill(c.state,b.dataset.undoBill))){refresh();api.toast('账单已恢复');}}catch(e){api.toast(e.message);}});
$('#billInventory')?.addEventListener('change',e=>{e.target.checked=false;api.toast('用品库存暂未配置，本次不会入库或扣减。');});
const photoRender=()=>{const target=$('#billPhotos');if(target)target.innerHTML=u.photos.map((p,i)=>`<div><img src="${E(p)}" alt="账单照片"><button type="button" data-remove-bill-photo="${i}" aria-label="移除照片${i+1}">×</button></div>`).join('');document.querySelectorAll('[data-remove-bill-photo]').forEach(b=>b.onclick=()=>{u.photos.splice(Number(b.dataset.removeBillPhoto),1);api.setDirty();photoRender();});};
if(c.page==='billdetail')u.photos=[...(c.state.bills.find(b=>b.id===u.editId)?.photos||[])];
const savePhotos=()=>{if(c.page!=='billdetail')return true;try{const b=c.state.bills.find(b=>b.id===u.editId);return api.persist(saveBill(c.state,{...b,photos:[...u.photos],updated:new Date().toISOString()}));}catch(e){api.toast(e.message);return false;}};
document.querySelectorAll('[data-remove-bill-photo]').forEach(b=>b.onclick=()=>{if(c.page==='billdetail'&&!confirm('移除这张账单照片？'))return;u.photos.splice(Number(b.dataset.removeBillPhoto),1);if(savePhotos()){if(c.page==='billdetail')refresh();else{api.setDirty();photoRender();}}});
const addPhotos=async files=>{const old=[...u.photos];for(const f of files){if(u.photos.length>=9){api.toast('最多添加9张照片');break;}if(f.size>20*1024*1024){api.toast('单张照片不能超过20MB');continue;}try{u.photos.push(await api.compress(f));}catch{api.toast('照片读取失败');}}if(savePhotos()){if(c.page==='billdetail')refresh();else{api.setDirty();photoRender();}}else u.photos=old;};
$('#billPhotoInput')?.addEventListener('change',e=>addPhotos(e.target.files));$('#billPhotoExtra')?.addEventListener('change',e=>addPhotos(e.target.files));
if(form){const old=c.state.bills.find(b=>b.id===u.editId),parent=c.state.bills.find(b=>b.id===(u.refundParent||old?.parentId));const split=$('#billSplit'),panel=$('#billSplitPanel');const equal=()=>{try{const selected=[...form.querySelectorAll('[name=splitPet]:checked')].map(el=>splitOwners(c.state,old).find(p=>p.id===el.value));const total=cents(form.elements.amount.value);for(const a of splitCents(total,selected))form.querySelector(`[data-allocation="${CSS.escape(a.petId)}"]`).value=(a.cents/100).toFixed(2);api.setDirty();}catch(e){api.toast(e.message);}};
split.addEventListener('change',()=>{if(split.checked&&splitOwners(c.state,old).length<2){split.checked=false;return api.toast('至少添加两只宠物后使用分摊');}panel.hidden=!split.checked;if(split.checked&&!form.querySelector('[name=splitPet]:checked')){form.querySelectorAll('[name=splitPet]').forEach(el=>el.checked=true);if(form.elements.amount.value)equal();}api.setDirty();});$('#equalSplit')?.addEventListener('click',equal);
form.elements.date.addEventListener('change',()=>$('#billDateDisplay').textContent=day(form.elements.date.value));
form.addEventListener('submit',e=>{e.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;try{const f=new FormData(form),amount=cents(f.get('amount'));let allocations;if(parent)allocations=refundAllocations(c.state,parent.id,amount,old?.id);else if(split.checked){const selected=[...form.querySelectorAll('[name=splitPet]:checked')];if(selected.length<2)throw Error('分摊至少选择两只宠物');allocations=selected.map(el=>{const p=splitOwners(c.state,old).find(p=>p.id===el.value);return {petId:p.id,petName:p.name,cents:cents(form.querySelector(`[data-allocation="${CSS.escape(p.id)}"]`).value,true)};});}else{const pid=f.get('petId');if(!pid)throw Error('请选择账单所属宠物');const p=c.state.pets.find(p=>p.id===pid);const snapshot=old?.allocations.find(a=>a.petId===pid);if(pid!=='public'&&!p&&!snapshot)throw Error('请选择存在的宠物');allocations=[{petId:pid==='public'?null:pid,petName:pid==='public'?'公共支出':p?.name||snapshot.petName,cents:amount}];}const bill={...old,id:old?.id||crypto.randomUUID(),type:parent?'refund':'expense',parentId:parent?.id||null,cents:amount,category:parent?.category||f.get('category'),date:f.get('date'),name:f.get('name').trim(),note:f.get('note'),allocations,photos:[...u.photos],created:old?.created||new Date().toISOString(),updated:new Date().toISOString(),deletedAt:null};if(api.persist(saveBill(c.state,bill))){api.clearDirty();u.editId=bill.id;u.refundParent=null;api.go(old?'billdetail':'ledger');api.toast('账单已保存');}}catch(e){api.toast(e.message);}finally{button.disabled=false;}});}
const initial=$('#investmentForm');if(initial){const t=investment(c.state,u.settingScope);initial.elements.initial.addEventListener('input',()=>{try{const n=cents(initial.elements.initial.value,true);$('#initialPreview').textContent=yen(n);$('#investmentPreview').textContent=yen(n+t.net);}catch{}});initial.addEventListener('submit',e=>{e.preventDefault();try{const value=cents(initial.elements.initial.value,true);if(api.persist({...c.state,initialInvestments:{...c.state.initialInvestments,[u.settingScope]:value}})){api.clearDirty();api.go('ledger');api.toast('累计投入设置已保存');}}catch(e){api.toast(e.message);}});}
}

